<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($pageTitle) ?> | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/account.css"><link rel="stylesheet" href="/assets/css/customer.css"></head>
<body class="dashboard-page"><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/account">Dashboard</a><a href="/logout">Sign out</a></nav></header>
<main class="customer-shell"><p class="eyebrow">Customer account</p><h1><?= htmlspecialchars($heading) ?></h1><?php if ($message): ?><p class="auth-success"><?= htmlspecialchars($message) ?></p><?php endif; ?><?php if ($error): ?><p class="auth-error"><?= htmlspecialchars($error) ?></p><?php endif; ?>
<?php if ($section === 'profile'): ?><section class="settings-panel"><h2>Profile details</h2><form class="settings-form" method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><label>Full name<input name="name" required value="<?= htmlspecialchars($user['name']) ?>"></label><label>Phone<input name="phone" value="<?= htmlspecialchars($user['phone'] ?? '') ?>"></label><button class="button" type="submit">Save profile</button></form></section>
<?php elseif ($section === 'addresses'): ?><section class="settings-panel"><h2>Saved addresses</h2><?php foreach ($addresses as $address): ?><article class="address-card"><div><strong><?= htmlspecialchars($address['label']) ?></strong><p><?= htmlspecialchars($address['recipient_name']) ?><br><?= htmlspecialchars($address['address_line1']) ?><br><?= htmlspecialchars($address['city']) ?>, <?= htmlspecialchars($address['state']) ?> <?= htmlspecialchars($address['postal_code']) ?><br><?= htmlspecialchars($address['phone']) ?></p></div><form method="post" action="/addresses/delete"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="address_id" value="<?= htmlspecialchars((string) $address['id']) ?>"><button class="button button-muted" type="submit">Delete address</button></form></article><?php endforeach; ?><h2>Add address</h2><form class="settings-form" method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><label>Label<input name="label" value="Home"></label><label>Recipient name<input name="recipient_name" required></label><label>Address<input name="address_line1" required></label><div class="form-columns"><label>City<input name="city" required></label><label>State<input name="state" required></label></div><div class="form-columns"><label>Postal code<input name="postal_code" required></label><label>Phone<input name="phone" required></label></div><label><input name="is_default" type="checkbox" value="1"> Make default address</label><button class="button" type="submit">Save address</button></form></section>
<?php else: ?><section class="settings-panel"><h2>Your wishlist</h2><div class="wishlist-grid"><?php foreach ($wishlist as $item): ?><a href="/product/<?= urlencode($item['slug']) ?>"><img loading="lazy" src="<?= htmlspecialchars($item['image']) ?>" alt="<?= htmlspecialchars($item['name']) ?>"><strong><?= htmlspecialchars($item['name']) ?></strong><span>₹<?= number_format((float) $item['price'], 0) ?></span></a><?php endforeach; ?></div><?php if (!$wishlist): ?><p class="empty-state">Your wishlist is waiting for something special.</p><?php endif; ?></section><?php endif; ?></main></body></html>
